"""Calibrated reference data for watermark detection and inverse alpha reconstruction."""
import numpy as np
import base64

_ALPHA_B64 = ""
_TMPL_B64 = ""

# Pure white watermark overlay vector (BGR)
WATERMARK_COLOR_BGR = np.array([255.0, 255.0, 255.0], dtype=np.float32)
BASE_WIDTH = 1376.0
BASE_HEIGHT = 768.0
NOMINAL_CENTER_X_REL = 1278.0 / 1376.0  # 0.928779
NOMINAL_CENTER_Y_REL = 671.0 / 768.0    # 0.873698
NOMINAL_BOX_SIZE_REL = 64.0 / 768.0     # 0.083333

def get_calibrated_alpha() -> np.ndarray:
    raw = base64.b64decode(_ALPHA_B64)
    return np.frombuffer(raw, dtype=np.float32).reshape((64, 64)).copy()

def get_calibrated_template() -> np.ndarray:
    raw = base64.b64decode(_TMPL_B64)
    return np.frombuffer(raw, dtype=np.float32).reshape((64, 64)).copy()
